SELECT ?s ?point ?ts WHERE {
  ?s a brick:AirHandlingUnit .
  FILTER(str(?s) LIKE "%AHU03%" || str(?s) LIKE "%03%")
  ?s brick:hasPoint ?point .
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?s ?label WHERE {
  ?s a brick:AirHandlingUnit .
  ?s rdfs:label ?label .
  FILTER(CONTAINS(str(?label), "AHU03"))
}

SELECT ?s ?label WHERE {
  OPTIONAL { ?s rdfs:label ?label . }
  FILTER(str(?s) CONTAINS "HU" OR str(?label) CONTAINS "AHU")
} LIMIT 40

SELECT ?ahu ?label ?point ?pclass WHERE {
  ?ahu a brick:AirHandlingUnit .
  OPTIONAL { ?ahu rdfs:label ?label . }
  OPTIONAL { ?ahu brick:hasPoint ?point . ?point brick:hasParameter ?pclass . }
}

